import{_ as a,o as t,c as s,a0 as i}from"./chunks/framework.BxCN1dRw.js";const u=JSON.parse('{"title":"Walkthrough: The bilingual public site","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/public-site"},"headers":[],"relativePath":"en/tutorials/public-site.md","filePath":"en/tutorials/public-site.md"}'),n={name:"en/tutorials/public-site.md"};function o(r,e,h,l,d,c){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="walkthrough-the-bilingual-public-site" tabindex="-1">Walkthrough: The bilingual public site <a class="header-anchor" href="#walkthrough-the-bilingual-public-site" aria-label="Permalink to &quot;Walkthrough: The bilingual public site&quot;">​</a></h1><p>The public site consists of four parts — Landing, Documentation, Blog and Downloads: an unauthenticated visitor understands the template from a concise brand home, enters the documentation in their language from the top navigation, and Blog and Downloads keep stable entries that honestly say &quot;Coming soon&quot;. This chapter walks the four entries as a visitor first, then explains, as a maintainer, how the pages are declared, how the copy stays truthful, how the example showcase leaves with the example, and the rules for language, theme and the deployment base.</p><h2 id="_1-try-it-first-the-four-entries-and-the-public-paths" tabindex="-1">1. Try it first: the four entries and the public paths <a class="header-anchor" href="#_1-try-it-first-the-four-entries-and-the-public-paths" aria-label="Permalink to &quot;1. Try it first: the four entries and the public paths&quot;">​</a></h2><p>Build and browse the site:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # Renders the bilingual site and verifies its navigation</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # Local dev server for editing while you look</span></span></code></pre></div><p>The Chinese entries live at the root: <code>/</code> (Landing), <code>/docs/</code> (the documentation), <code>/blog/</code> and <code>/downloads/</code>; English mirrors each of them under <code>/en/</code>. Language is decided by the path: <code>/en/blog/</code> serves the English page, and the site performs no device-language redirects. The top navigation&#39;s &quot;English / 中文&quot; switch follows the counterpart page recorded in the frontmatter, so it always lands on a page that exists. Old chapter deep links (such as <code>/en/getting-started/quickstart</code>) are unaffected by the redesign.</p><h2 id="_2-the-information-structure-expo-s-four-beats" tabindex="-1">2. The information structure: Expo&#39;s four beats <a class="header-anchor" href="#_2-the-information-structure-expo-s-four-beats" aria-label="Permalink to &quot;2. The information structure: Expo&#39;s four beats&quot;">​</a></h2><p>The Landing follows the information structure of Expo&#39;s home while claiming only delivered capabilities:</p><ol><li><strong>Value proposition + primary action</strong>: one sentence for the template (the README&#39;s own wording), with the primary button entering the Documentation in the current language and a GitHub repository entry beside it.</li><li><strong>The usage flow</strong>: start the stack → follow the tutorials → compose/remove the example → deploy and back up, each step linking to a real chapter.</li><li><strong>Real capabilities</strong>: every capability card links an existing tutorial chapter or the v1 coverage page; there is no &quot;planned / coming soon&quot; capability card.</li><li><strong>The closing call to action</strong>: back to the documentation.</li></ol><p>The discipline for a new card: confirm the capability has a row in <a href="./../architecture/v1-coverage">v1 capability coverage and acceptance</a> before deciding on the card and its link; keep the wording consistent with the chapter it points at, and never invent numbers (performance, scale, user counts).</p><h2 id="_3-how-pages-are-declared-site-json-and-the-renderer" tabindex="-1">3. How pages are declared: site.json and the renderer <a class="header-anchor" href="#_3-how-pages-are-declared-site-json-and-the-renderer" aria-label="Permalink to &quot;3. How pages are declared: site.json and the renderer&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/cdc0b7ddfa2dc2c82b5883ae3f8de743608f4e1e/docs/site.json" target="_blank" rel="noreferrer">site.json</a> is the only place to declare them. The Landing and the two placeholder pages are ordinary page entries carrying <code>layout: &quot;page&quot;</code>: bilingual pairs (<code>sourceEn</code>/<code>titleEn</code>) plus paired <code>pageTitle</code>/<code>pageTitleEn</code> and <code>pageDescription</code>/<code>pageDescriptionEn</code> — the renderer writes them into the page frontmatter, so each page&#39;s <code>&lt;title&gt;</code> and meta description honestly reflect the &quot;Coming soon&quot; state. The validation lives in <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/cdc0b7ddfa2dc2c82b5883ae3f8de743608f4e1e/scripts/lib/docs-locales.mjs" target="_blank" rel="noreferrer">docs-locales.mjs</a>: the meta must be paired and may only appear on layout pages; half a pair fails the build.</p><p>A layout page stays out of the sidebar (the renderer also writes <code>sidebar: false</code>) and appears only in the top navigation; the four page kinds share the same navigation, footer, visual tokens and light/dark rules. The Landing sources are plain Markdown with a little constrained HTML (<code>docs/index.md</code> and the adjacent <code>docs/index.en.md</code>), styled in <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/cdc0b7ddfa2dc2c82b5883ae3f8de743608f4e1e/apps/docs/.vitepress/theme/custom.css" target="_blank" rel="noreferrer">custom.css</a> with the same <code>--vp-*</code> tokens the documentation uses.</p><h2 id="_4-the-boundary-of-coming-soon" tabindex="-1">4. The boundary of Coming soon <a class="header-anchor" href="#_4-the-boundary-of-coming-soon" aria-label="Permalink to &quot;4. The boundary of Coming soon&quot;">​</a></h2><p>Blog and Downloads are placeholders in this round: no article list or publishing management, no download catalog, version/platform picker, installer service, subscription form or progress promises. The placeholder&#39;s obligation is honesty — say what a visitor can do now (return home, read the documentation, watch the repository) and never fabricate articles, dates or release assets; the page title and meta state the status truthfully. When the blog or the download service arrives, replace the placeholder content; the entry paths and the navigation stay stable.</p><h2 id="_5-the-ownership-of-the-example-showcase" tabindex="-1">5. The ownership of the example showcase <a class="header-anchor" href="#_5-the-ownership-of-the-example-showcase" aria-label="Permalink to &quot;5. The ownership of the example showcase&quot;">​</a></h2><p>The Landing&#39;s &quot;reference example&quot; section sits entirely between the <code>example:knowledge:landing:start/end</code> markers — it is the knowledge-base example&#39;s showcase. Landing text outside the markers may only link Core chapters; the post-removal <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/cdc0b7ddfa2dc2c82b5883ae3f8de743608f4e1e/scripts/check-docs-build.mjs" target="_blank" rel="noreferrer">docs:build</a> checks every link&#39;s existence, and the example&#39;s cards disappear with the markers as one block, leaving no dead entries behind. Run the drill yourself:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/ui16-drill</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/example-remove.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/ui16-drill</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/ui16-drill</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # The showcase is trimmed; every remaining link resolves</span></span></code></pre></div><p>CI&#39;s example-removal job does the same on every pull request; the Core-only site must keep building and publishing.</p><h2 id="_6-language-theme-and-deployment" tabindex="-1">6. Language, theme and deployment <a class="header-anchor" href="#_6-language-theme-and-deployment" aria-label="Permalink to &quot;6. Language, theme and deployment&quot;">​</a></h2><p>The theme preference is saved locally in the browser by VitePress&#39;s appearance toggle (<code>localStorage</code>); it never syncs across devices. Language follows the path only — the site promises no automatic cross-site following. Deployment rides the existing static pipeline: GitHub Pages publishes from <code>main</code> (see <a href="./../getting-started/publish-docs">publishing the documentation site</a>), repository sub-paths are carried by the base, and a custom base is built with <code>DOCS_BASE=/your-base/ pnpm docs:build</code> and verified by the built-in check — the public-site browser journeys (<code>just e2e-docs</code>) include one custom-base smoke pass.</p><h2 id="_7-run-this-chapter-s-checks" tabindex="-1">7. Run this chapter&#39;s checks <a class="header-anchor" href="#_7-run-this-chapter-s-checks" aria-label="Permalink to &quot;7. Run this chapter&#39;s checks&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:check</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # The bilingual contract, paired meta, links and snippets</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # Rendering + post-build navigation check (base resolution included)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> e2e-docs</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # Public-site journeys: four entries, CTA, placeholders, switching, theme, narrow screens, custom base</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # The main gate</span></span></code></pre></div><p>Contrast rides the documentation site&#39;s settled tokens: body text clears WCAG AA by a wide margin on both surfaces; the only self-drawn decoration, the small dots beside card headings, keep ≥3:1 against the background in both modes (the non-text threshold), with a brighter violet-500 compensating the purple dot in dark mode.</p><p>The public site&#39;s page kinds, navigation and renderer are all Core: the placeholder pages, the top bar and the whole rendering chain appear in no ownership manifest, and the site builds and publishes after example removal. The Landing source file is a Core page too, but it registers the <code>example:knowledge:landing</code> markers in the example ownership manifest&#39;s registrationMarkers — the example owns not the page but the showcase section between the markers, which the removal trims as one block; the only example-related part of the browser journeys is that section.</p><hr><p>Source version：<code>cdc0b7ddfa2d</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/cdc0b7ddfa2dc2c82b5883ae3f8de743608f4e1e/docs/tutorials/30-public-site.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,27)])])}const g=a(n,[["render",o]]);export{u as __pageData,g as default};
